def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    ys, xs = np.where(g != bg)
    y0, y1 = ys.min(), ys.max()
    x0, x1 = xs.min(), xs.max()
    cy, cx = (y0 + y1) // 2, (x0 + x1) // 2
    H, W = g.shape

    # all 8 symmetries of the square acting on offsets (dy, dx)
    def images(dy, dx):
        return {(dy, dx), (-dy, dx), (dy, -dx), (-dy, -dx),
                (dx, dy), (-dx, dy), (dx, -dy), (-dx, -dy)}

    for y, x in zip(ys, xs):
        col = g[y, x]
        dy, dx = y - cy, x - cx
        for ey, ex in sorted(images(dy, dx)):
            ty, tx = cy + ey, cx + ex
            if 0 <= ty < H and 0 <= tx < W and out[ty, tx] == bg:
                out[ty, tx] = col
                emit(out.copy(), f"Mirror the lone cell at ({y},{x}) of colour {col} about centre ({cy},{cx}): paint ({ty},{tx})")

    emit(out.copy(), "Symmetric figure completed")
    return out
